  isMobileMode() {
    return window.innerWidth < 768 || window.innerHeight < 581;
  }
  toggleCodePart(codeType) {
    let showHtmlForMobile = this.runtimeLayoutData().mobileLayoutData?.showHtmlForMobile;
    let showCssForMobile = this.runtimeLayoutData().mobileLayoutData?.showCssForMobile;
    let showJsForMobile = this.runtimeLayoutData().mobileLayoutData?.showJsForMobile;
    let showResultForMobile = this.runtimeLayoutData().mobileLayoutData?.showResultForMobile;
    switch (codeType) {
      case "html":
        showHtmlForMobile = !showHtmlForMobile;
        showCssForMobile = false;
        showJsForMobile = false;
        if (!showHtmlForMobile) {
          showResultForMobile = true;
        }
        break;
      case "css":
        showCssForMobile = !showCssForMobile;
        showHtmlForMobile = false;
        showJsForMobile = false;
        if (!showCssForMobile) {
          showResultForMobile = true;
        }
        break;
      case "js":
        showJsForMobile = !showJsForMobile;
        showHtmlForMobile = false;
        showCssForMobile = false;
        if (!showJsForMobile) {
          showResultForMobile = true;
        }
        break;
      case "result":
        if (showJsForMobile || showHtmlForMobile || showCssForMobile) {
          showResultForMobile = !showResultForMobile;
        }
        break;
    }
    this.store.dispatch(updateRuntimeLayoutDataAction({
      mobileLayoutData: {
        showHtmlForMobile,
        showCssForMobile,
        showJsForMobile,
        showResultForMobile
      }
    }));
    if (!showResultForMobile) {
      if (document.querySelector("app-iframe-part")?.classList.contains("hide-mobile")) {
      }
    }
  }
