  getCodePartGutterStyle(type) {
    let obj = {
      "flex-basis": "5px"
    };
    if (this.fiddleData().layout == 1 || this.fiddleData().layout == 3) {
      if (type == "main-container") {
        obj.cursor = "col-resize";
      } else if (type == "html-css" || type == "css-js") {
        obj.cursor = "row-resize";
      }
    } else {
      if (type == "main-container") {
        obj.cursor = "row-resize";
      } else if (type == "html-css" || type == "css-js") {
        obj.cursor = "col-resize";
      }
    }
    return obj;
  }
  validateFiddleRessources() {
    let selectedRessourceAssets = this.ressourcesComponent.validateRessources();
    let htmlCode = this.fiddleData().html;
    selectedRessourceAssets.forEach((el, index, arr) => {
      htmlCode = arr[arr.length - 1 - index] + htmlCode;
    });
    this.store.dispatch(updateFiddleDataAction({ html: htmlCode }));
    this.htmlPart.htmlCode.setValue(htmlCode);
    this.ressourcesComponent.resetCurrentRessourceChoice();
    this.ressourcesComponent.emptySelectedRessourceAssets();
    this.notifService.showInfo("Ressources prepended to HTML code.");
    this.hideRessourcesModal();
  }
  getVerticalModeState(codePartType) {
    if (this.fiddleData().layout == 2 || this.fiddleData().layout == 4) {
      switch (codePartType) {
        case "html":
          if (this.fiddleData().htmlPartSize < 230) {
            return true;
          } else {
            return false;
          }
        case "js":
          if (this.fiddleData().jsPartSize < 280) {
            return true;
          } else {
            return false;
          }
        case "css":
          if (this.fiddleData().cssPartSize < 230) {
            return true;
          } else {
            return false;
          }
      }
    }
    return false;
  }
